typedef unsigned int u_int;

class game
{
public:
	bool is_paused() const;
};

struct nglTexture;
struct nglQuadVertex
{
	float X, Y;
	float U, V;
	u_int Color;
};
struct nglQuad
{
	nglQuadVertex Verts[4];
	float Z;
	u_int MapFlags;
	u_int BlendMode;
	u_int BlendModeConstant;
	nglTexture* Tex;
};

enum
{
	NGLCLEAR_Z = 1,
	NGLCLEAR_STENCIL = 4,
	NGLMAP_BILINEAR_FILTER = 2,
	NGLMAP_CLAMP_U = 0x10,
	NGLMAP_CLAMP_V = 0x20,
	NGLBM_CONST_BLEND = 3
};

extern bool BLUR_Active;
extern float BLUR_StartTime;
extern float BLUR_Duration;
extern float BLUR_Alpha;
extern game* g_game_ptr;
float TIMER_GetTotalSec();
u_int RoundUpToPowerOf2(u_int);
void nglListBeginScene(void* SortInfo = 0);
void nglSetClearFlags(u_int);
nglTexture* nglGetFrontBufferTex();
void nglInitQuad(nglQuad*);
void nglSetQuadMapFlags(nglQuad*, u_int);
void nglSetQuadTex(nglQuad*, nglTexture*);
void nglSetQuadColor(nglQuad*, u_int);
void nglSetQuadRect(nglQuad*, float, float, float, float);
int nglGetScreenWidth();
int nglGetScreenHeight();
void nglSetQuadZ(nglQuad*, float);
void nglSetQuadUV(nglQuad*, float, float, float, float);
void nglSetQuadBlend(nglQuad*, u_int, u_int = 0);
void nglListAddQuad(nglQuad*);
void nglListEndScene();

inline int FTOI(float input)
{
	register float output;
	__asm__ volatile ("cvt.w.s %0, %1" : "=f" (output) : "f" (input));
	return (int&)output;
}

#define NGL_RGBA32(r, g, b, a) ((int)((r)+1)>>1) | (((int)((g)+1)>>1) << 8) | (((int)((b)+1)>>1) << 16) | (((int)((a)+1)>>1) << 24)

void BLUR_Draw(void)
{

	// These magic numbers get the PS2 to be blur free for the IGO's
	static float MAGICx1=-.55,MAGICy1=-.55, MAGICx2=.55, MAGICy2=.5;
	// no access to front buffer on GC
	if (BLUR_Active && !g_game_ptr->is_paused())
	{
		float progress = (TIMER_GetTotalSec() - BLUR_StartTime) / BLUR_Duration;
		if (progress >= 1)
		{
			BLUR_Active = false;
		}
#if defined(TARGET_PS2)
		float alpha = BLUR_Alpha * (1 - progress / 2) * 128;
#else
		float alpha = BLUR_Alpha * (1 - progress / 2) * 255;
#endif

#ifdef TARGET_GC
#if (NGL > 0x010700)
		#warning "need reimplementation of motion blur that doesn't suck -- mdm"
#else
    nglGCMotionBlur( NGL_RGBA32( 255, 255, 255, alpha ) );
#endif
#else
		nglListBeginScene();
		nglSetClearFlags(NGLCLEAR_Z | NGLCLEAR_STENCIL);
		float zmax = 1;
		nglTexture *Tex = nglGetFrontBufferTex();
		nglQuad q;
		nglInitQuad(&q);
		nglSetQuadMapFlags(&q, NGLMAP_CLAMP_U | NGLMAP_CLAMP_V | NGLMAP_BILINEAR_FILTER);
		nglSetQuadTex(&q, Tex);
		nglSetQuadColor(&q, NGL_RGBA32(255, 255, 255, 255));
#ifdef TARGET_PS2
		nglSetQuadRect(&q, MAGICx1 , MAGICy1, RoundUpToPowerOf2(nglGetScreenWidth())-MAGICx2, RoundUpToPowerOf2(nglGetScreenHeight())-MAGICy2);
#else
		nglSetQuadRect(&q, 0, 0, nglGetScreenWidth(), nglGetScreenHeight());
#endif
		nglSetQuadZ(&q, zmax);
		nglSetQuadUV(&q, 0, 0, 1, 1);
		nglSetQuadBlend(&q, NGLBM_CONST_BLEND, FTOI(alpha));
		nglListAddQuad(&q);
		nglListEndScene();
#endif	//TARGET_GC
	}
}
